            elif requestClass == CAP_SEND_FILE:
                if moreTLVs.has_key(11):
                    return
                name = moreTLVs[10001][9:-7]
                desc = moreTLVs[12]
                self.receiveSendFileRequest(user, name, desc, cookie)
            else:
                pass
        else:
            pass

