def __isDirOrParent(id_a, id_b): 
    #returns true is a == b or is a is a parent of b
    d = M.Folder.objects.get(pk=id_b)
    while d.parent_id is not None: 
        if d.id == id_a: 
            return True
        d = d.parent
    return id_a == d.id

