        while len(YAPI._DataEvents) > 0:
            YAPI.yapiLockFunctionCallBack(errmsgRef)
            if not (len(YAPI._DataEvents)):
                YAPI.yapiUnlockFunctionCallBack(errmsgRef)
                break

            ev = YAPI._DataEvents.pop(0)
            YAPI.yapiUnlockFunctionCallBack(errmsgRef)
            ev.invokeData()
        return YAPI.SUCCESS

