    attrs['sunetid'] = sunetid
    attrs['issue'] = issue.id
    attrs['ip_address'] = request.META['REMOTE_ADDR']
    attrs['signed_at'] = datetime.now()

    form = SignatureForm(issue, attrs)

    if form.is_valid() and issue.petition_open():
